def main():
    n = int(input())
    q = list(map(int, input().split()))
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    max_servings = 0

    for x in range(max(q) // min(a) + 1):
        y = float('inf')
        for i in range(n):
            if q[i] < x * a[i]:
                y = -1
                break
            if b[i] > 0:
                y = min(y, (q[i] - x * a[i]) // b[i])
        if y != -1:
            max_servings = max(max_servings, x + y)

    print(max_servings)

